def transform(grid):
    from collections import Counter, defaultdict, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the multicolour legend component (diagonal contacts count).
    seen = set()
    key = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            colors = set()
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                colors.add(grid[y][x])
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if not (dy or dx):
                            continue
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                                grid[yy][xx] != bg and (yy, xx) not in seen):
                            seen.add((yy, xx))
                            q.append((yy, xx))
            if len(colors) > 1 and len(cells) > len(key):
                key = set(cells)

    mapping = {}
    if key:
        r0 = min(r for r, c in key)
        r1 = max(r for r, c in key)
        c0 = min(c for r, c in key)
        for r in range(r0, r1 + 1):
            src = grid[r][c0]
            if src == bg:
                continue
            dst = grid[r][c0 + 1] if c0 + 1 < w else bg
            if dst != bg:
                mapping[src] = dst
            elif r1 - r0 + 1 >= 3:
                mapping[src] = bg
            else:
                # In a short, irregular legend a blank is not an explicit
                # erase entry; use the visible target colour.
                targets = [grid[y][c0 + 1] for y in range(r0, r1 + 1)
                           if c0 + 1 < w and grid[y][c0 + 1] != bg]
                if targets:
                    mapping[src] = Counter(targets).most_common(1)[0][0]

    # Find monochrome L triominoes.
    seen = set()
    ls = defaultdict(list)
    solids = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in key or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] == color and
                            (yy, xx) not in key and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        q.append((yy, xx))

            if len(cells) == 3:
                top = min(y for y, x in cells)
                left = min(x for y, x in cells)
                if (max(y for y, x in cells) == top + 1 and
                        max(x for y, x in cells) == left + 1):
                    missing = next((y, x)
                                   for y in (top, top + 1)
                                   for x in (left, left + 1)
                                   if (y, x) not in cells)
                    ls[color].append((cells, missing))
            elif len(cells) == 4:
                ys = [y for y, x in cells]
                xs = [x for y, x in cells]
                if max(ys) - min(ys) == 1 and max(xs) - min(xs) == 1:
                    solids.append((color, cells))

    # Oppositely oriented Ls of the same colour frame a rectangle.
    rectangles = []
    for color, group in ls.items():
        if color not in mapping:
            continue
        for i in range(len(group)):
            for j in range(i + 1, len(group)):
                a, ma = group[i]
                b, mb = group[j]
                if (ma[0] - mb[0]) * (ma[1] - mb[1]) >= 0:
                    continue
                ends = a | b
                top = min(y for y, x in ends)
                bottom = max(y for y, x in ends)
                left = min(x for y, x in ends)
                right = max(x for y, x in ends)
                rectangles.append((top, left, color, mapping[color],
                                  bottom, right, ends))

    out = [row[:] for row in grid]
    # Draw from top to bottom; a later framed area can cover an earlier one.
    for top, left, color, fill, bottom, right, ends in sorted(rectangles):
        for y in range(top, bottom + 1):
            for x in range(left, right + 1):
                if (y, x) not in ends:
                    out[y][x] = fill

    # Recolour isolated solid 2x2 objects using the same legend.
    for color, cells in solids:
        if color in mapping:
            for y, x in cells:
                out[y][x] = mapping[color]

    return out
